import{_ as a,o as i,c as t,a2 as s}from"./chunks/framework.DZhUhjDB.js";const m=JSON.parse('{"title":"Área 1 — Ciberseguridad Ofensiva y Base Purple","description":"Área 1 — Ciberseguridad Ofensiva y Base Purple","frontmatter":{"title":"Área 1 — Ciberseguridad Ofensiva y Base Purple","description":"Área 1 — Ciberseguridad Ofensiva y Base Purple"},"headers":[],"relativePath":"modules/red-team/index.md","filePath":"modules/red-team/index.md","lastUpdated":1787529976000}'),o={name:"modules/red-team/index.md"};function r(n,e,l,d,c,p){return i(),t("div",null,[...e[0]||(e[0]=[s(`<blockquote><p>🚀 <strong>¿Eres principiante?</strong> Antes de este módulo, revisa la <strong><a href="./../fundamentos/">base común del repo</a></strong> (1 carpeta atrás). Ahí están los conceptos que necesitas para que esto te haga sentido.</p><p>Elige tu ruta de aprendizaje: 🛡️ <a href="./../fundamentos/rutas/ruta-defensor">Defensor</a> · ⚔️ <a href="./../fundamentos/rutas/ruta-atacante">Atacante</a> · 🤖 <a href="./../fundamentos/rutas/ruta-ai-security">AI Security</a></p></blockquote><h1 id="🔴-area-1-—-ciberseguridad-ofensiva-y-base-purple" tabindex="-1">🔴 Área 1 — Ciberseguridad Ofensiva y Base Purple</h1><blockquote><p><strong>Misión de el área:</strong> Formarte en los fundamentos técnicos de la ciberseguridad ofensiva (hacking ético) y darte la base práctica que luego alimenta rutas Purple Team, Blue Team y DevSecOps.</p></blockquote><p>Aquí se aprende <strong>a pensar como atacante para defender mejor</strong>. Es la columna vertebral técnica de la plataforma.</p><hr><h2 id="🎯-objetivos-formativos" tabindex="-1">🎯 Objetivos formativos</h2><p>Al completar los módulos clave de esta área deberías ser capaz de:</p><ul><li>Entender y aplicar el <strong>ciclo completo de un pentest</strong>: reconocimiento, enumeración, explotación, post-explotación y reporte.</li><li>Usar herramientas ofensivas estándar (Nmap, Gobuster, Burp, etc.) con criterio, no solo como &quot;listas de comandos&quot;.</li><li>Analizar vulnerabilidades y priorizarlas según impacto real.</li><li>Documentar tus hallazgos de forma profesional (informes claros, reproducibles y útiles para equipos técnicos y de negocio).</li><li>Conectar la visión ofensiva con la defensa (base para Purple Team).</li></ul><hr><h2 id="🧱-areas-clave-de-el-area-1" tabindex="-1">🧱 Áreas clave de el Área 1</h2><p>Los módulos de esta área se organizan alrededor de estas áreas:</p><ul><li><p><strong>Reconocimiento y OSINT técnico</strong></p><ul><li>Identificación de objetivos, rangos, dominios, tecnologías visibles.</li><li>Uso de herramientas de escaneo y recolección de información.</li></ul></li><li><p><strong>Análisis de vulnerabilidades</strong></p><ul><li>Interpretar resultados de escáneres.</li><li>Entender CWE, CVE, CVSS a nivel práctico.</li></ul></li><li><p><strong>Explotación Web y de Servicios</strong></p><ul><li>Ataques a aplicaciones web (inyecciones, auth, sesiones, etc.).</li><li>Explotación de servicios típicos (FTP, SSH, SMB, etc.) en entornos de laboratorio.</li></ul></li><li><p><strong>Post-explotación y movimiento lateral</strong></p><ul><li>Enumeración interna tras lograr acceso.</li><li>Escalada de privilegios en sistemas Windows/Linux.</li></ul></li><li><p><strong>Forense básico y registro de evidencias</strong></p><ul><li>Captura y preservación de evidencias en labs.</li><li>Uso básico de herramientas forenses para entender qué pasó.</li></ul></li><li><p><strong>Purple Team Base</strong></p><ul><li>Traducir técnicas ofensivas a detecciones y controles defensivos.</li><li>Mapear ataques a marcos como MITRE ATT&amp;CK.</li></ul></li></ul><hr><h2 id="🗺️-mapa-de-subdominios" tabindex="-1">🗺️ Mapa de subdominios</h2><table tabindex="0"><thead><tr><th>#</th><th>Subdominio</th><th>Fase Kill Chain</th><th>Tácticas MITRE</th></tr></thead><tbody><tr><td>01</td><td><a href="./01-reconocimiento-osint/">Reconocimiento OSINT</a></td><td>Reconnaissance</td><td>TA0043</td></tr><tr><td>02</td><td><a href="./02-pentesting-red-team/">Pentesting / Red Team</a></td><td>Múltiples</td><td>TA0001-TA0011</td></tr><tr><td>03</td><td><a href="./03-analisis-vulnerabilidades/">Análisis de Vulnerabilidades</a></td><td>Weaponization</td><td>TA0042</td></tr><tr><td>04</td><td><a href="./04-explotacion-web/">Explotación Web</a></td><td>Exploitation</td><td>TA0001</td></tr><tr><td>05</td><td><a href="./05-post-explotacion/">Post-Explotación</a></td><td>Actions on Objectives</td><td>TA0003-TA0008</td></tr><tr><td>06</td><td><a href="./06-forense-digital/">Forense Digital</a></td><td>Análisis</td><td>—</td></tr><tr><td>07</td><td><a href="./07-ingenieria-social/">Ingeniería Social</a></td><td>Initial Access</td><td>TA0001</td></tr><tr><td>08</td><td><a href="./08-criptografia/">Criptografía</a></td><td>Transversal</td><td>—</td></tr></tbody></table><hr><h2 id="🗂-estructura-tipo-de-cada-modulo" tabindex="-1">🗂 Estructura tipo de cada módulo</h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NN-nombre/</span></span>
<span class="line"><span>├── herramientas/      ← Una carpeta por herramienta + README con uso</span></span>
<span class="line"><span>├── tecnicas/          ← Procedimientos paso a paso</span></span>
<span class="line"><span>├── laboratorios/      ← Labs reproducibles (Docker / Vagrant / HTB/THM)</span></span>
<span class="line"><span>└── README.md          ← Índice del módulo</span></span></code></pre></div><p>Cada módulo usará <code>TEMPLATE-MODULO.md</code> como base: objetivos, teoría mínima, práctica guiada, evidencia y entregables de portafolio.</p><hr><h2 id="👤-perfiles-que-se-forman-en-esta-area" tabindex="-1">👤 Perfiles que se forman en esta área</h2><p>Esta área sirve de base para varios roles:</p><ul><li><p><strong>Hacker ético / Pentester junior</strong></p><ul><li>Foco en reconocer, explotar y documentar vulnerabilidades en entornos controlados.</li></ul></li><li><p><strong>Analista de seguridad / Blue Team junior</strong></p><ul><li>Usa la visión ofensiva para entender mejor qué detectar y cómo responder.</li></ul></li><li><p><strong>Purple Teamer</strong></p><ul><li>Conecta ataques con detecciones y mejoras de controles.</li></ul></li><li><p><strong>Futuro DevSecOps / ML-Security Engineer</strong></p><ul><li>Necesita entender qué vulnerabilidades existen en la práctica antes de automatizar o asegurar pipelines.</li></ul></li></ul><p>Más adelante se podrán definir roles específicos (por ejemplo, &quot;Red Team Operator&quot;, &quot;Purple Team Engineer&quot;) igual que se hizo con <code>prompt-engineer-security</code> en Área 3.</p><hr><h2 id="🔗-relacion-con-otras-areaes" tabindex="-1">🔗 Relación con otras áreaes</h2><ul><li><p><strong>Área 2 – Seguridad de la Información y Defensa (<code>02-SEGURIDAD-INFORMACION/</code>)</strong></p><ul><li>Toma las técnicas ofensivas vistas aquí y las aterriza en monitoreo, respuesta a incidentes, gestión de riesgos y cumplimiento.</li></ul></li><li><p><strong>Área 3 – IA, Agentes y Automatización (<code>03-IA-AGENTES-HERRAMIENTAS/</code>)</strong></p><ul><li>Usa lo aprendido aquí como base para crear agentes de OSINT/pentest y automatizaciones con IA.</li></ul></li><li><p><strong>Área 4 – Laboratorios (<code>04-LABORATORIOS/</code>)</strong></p><ul><li>Muchos labs de CTF, HTB, THM y labs propios estarán alineados con estos módulos.</li></ul></li></ul><hr><h2 id="📌-ruta-sugerida-dentro-de-el-area-1" tabindex="-1">📌 Ruta sugerida dentro de el Área 1</h2><p>Un camino recomendado para avanzar en esta área:</p><ol><li><p><strong><code>01-reconocimiento-osint/</code></strong></p><ul><li>Fundamentos de reconocimiento y OSINT técnico sin IA.</li><li>Uso de Nmap, whois, DNS, escaneos básicos.</li></ul></li><li><p><strong><code>02-pentesting-red-team/</code></strong></p><ul><li>Ciclo completo de pentest sobre máquinas de laboratorio.</li></ul></li><li><p><strong><code>03-analisis-vulnerabilidades/</code></strong></p><ul><li>Interpretar resultados de escáneres, priorizar findings y entender CWE/CVE.</li></ul></li><li><p><strong><code>04-explotacion-web/</code> y <code>05-post-explotacion/</code></strong></p><ul><li>Hacking web + movimiento lateral y escalada de privilegios.</li></ul></li><li><p><strong><code>06-forense-digital/</code> y <code>07-ingenieria-social/</code></strong></p><ul><li>Entender el impacto de ataques y la capa humana.</li></ul></li><li><p><strong><code>08-criptografia/</code></strong></p><ul><li>Base de cifrado, hashing, PKI y errores comunes en su implementación.</li></ul></li></ol><hr><h2 id="📂-entregables-tipicos-de-esta-area" tabindex="-1">📂 Entregables típicos de esta área</h2><p>En los módulos de esta área es común que generes:</p><ul><li>Informes de recon y pentest en Markdown/PDF.</li><li>Writeups de máquinas CTF (paso a paso, reproducibles).</li><li>Scripts simples (bash/Python) para automatizar pequeños pasos.</li><li>Notas y cheatsheets de comandos y técnicas.</li></ul><p>Todos estos se conectarán luego con <code>PORTAFOLIO.md</code> para que construyas una historia coherente de tu progreso ofensivo.</p><hr><div align="center"><p><strong><a href="./../README">⬅ Volver al README principal</a></strong> · <strong><a href="./../02-SEGURIDAD-INFORMACION/">🔵 Ir a Defensiva →</a></strong></p></div>`,38)])])}const g=a(o,[["render",r]]);export{m as __pageData,g as default};
